package org.apache.commons.lang.time;

import junit.framework.TestCase;
import java.util.Calendar;
import java.util.Date;

public class AgentBRT_Lang_53_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.OCTOBER, 10, 10, 10, 59); // Set time to 10:10:59
        calendar.set(Calendar.MILLISECOND, 0); // Ensure milliseconds are zero

        Date truncatedDate = DateUtils.truncate(calendar.getTime(), Calendar.SECOND);
        calendar.setTime(truncatedDate);

        // Expect the seconds to be truncated to 10:10:00
        assertEquals(0, calendar.get(Calendar.SECOND));
    }
}

